import os
import xml.etree.ElementTree as Et
from lxml import etree

from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output, log_operation,
)


class XmlFile:
    def __init__(self, path_to_xml):
        self.path_to_xml = path_to_xml
        self._xml_tree = self._load_xml()
        self._root_element = self._xml_tree.getroot()

    @property
    def xml_tree(self):
        return self._xml_tree

    @property
    def root_element(self):
        return self._root_element

    @log_input_and_output
    def check_if_element_exists(self, custom_element):
        """
        Checks if given element (tag) exists in XML tree.

        :param custom_element: tag of demanded element.
        :type custom_element: str
        :return True if any element is found, False otherwise
        :rtype: bool
        """
        return True if len([elem for elem in self.xml_tree.iter(custom_element)]) > 0 else False

    @log_input_and_output
    def check_if_element_exists_with_custom_attrib(self, custom_element, custom_attrib, attrib_value):
        """
        Checks if given element with specific tag, attribute and attribute value exists in XML tree.

        :param custom_element: tag of demanded element
        :type custom_element: str
        :param custom_attrib: attribute name of demanded element
        :type custom_attrib: str
        :param attrib_value: attribute value of demanded element
        :type attrib_value: str
        :return True if any element is found, False otherwise
        :rtype: bool
        """
        attributes = [elem.attrib for elem in self.xml_tree.iter(custom_element)]
        for attribute in attributes:
            if custom_attrib in attribute.keys() and attribute[custom_attrib] == attrib_value:
                return True
        return False

    @log_input_and_output
    def get_custom_elements_children_and_grandchildren(self, custom_element_name, xpath=False):
        """
        Gets list of dicts with tags, attributes, texts, and content of all children of element with given
        custom element name (tag) and also tags, attributes, texts of all grandchildren

        :param custom_element_name: tag of main element
        :type custom_element_name: str
        :param xpath: if True, uses xpath to find elements, otherwise uses iter method, default is False
        :type xpath: bool
        :return List of dicts with children and grandchildren info for every element with given tag, e.g. :
                [{'tag': 'Object', 'attributes': {'distName': 'btsInformation', 'class': 'Permanent'}, 'text': None,
                  'Object_content': [{'tag': 'created', 'attributes': {}, 'text': None, 'created_content': []},
                                     {'tag': 'owner', 'attributes': {}, 'text': '__internal_name__',
                                      'owner_content': []},
                                     {'tag': 'parameter', 'attributes': {}, 'text': None,
                                      'parameter_content': [{'tag': 'parameterName', 'attributes': {},
                                                            'text': 'BtsId'},
                                                            {'tag': 'value', 'attributes': {},
                                                             'text': 'N18xNl9VVEU1R1NJU09BVVRPMDIyXzQ3'}]}]}, ]
        :rtype: list of dict
        """
        if xpath:
            elements = [elem for elem in self.xml_tree.iterfind(custom_element_name)]
        else:
            elements = [elem for elem in self.xml_tree.iter(custom_element_name)]

        elements_content = []
        for ind, element in enumerate(elements):
            attribute_dict = {}
            for name, value in element.attrib.items():
                attribute_dict[name] = value
            elements_content.append({'tag': element.tag,
                                     'attributes': attribute_dict,
                                     'text': element.text,
                                     element.tag + '_content': self._get_all_children_for_element(element)})
            for child_ind, child in enumerate(element):
                elements_content[ind][element.tag + '_content'][child_ind][child.tag + '_content'] = \
                    self._get_all_children_for_element(child)
        return elements_content

    def _load_xml(self):
        """
        Parse XML file to ElementTree object.
        :return: ElementTree object
        :rtype: ElementTree
        """
        try:
            return Et.parse(self.path_to_xml)
        except Et.ParseError:
            log_operation(f"Couldn't load XML file: {self.path_to_xml} using module Et.parse; attempting to repair.")
            XmlFile.repair_xml_file(self.path_to_xml)
        return Et.parse(self.path_to_xml)

    @staticmethod
    @log_input_and_output
    def check_element_content(element, searched_content):
        """
        Checks if the given element contains all specified content provided in `searched_content`.
        :param element: element from `get_custom_elements_children_and_grandchildren` method e.g.:
               {'tag': 'managedObject', 'attributes': {'class': 'SupportedFeature', 'distName': 'supported41'}, 'text': ',
               'managedObject_content': [{'tag': 'parameter', 'attributes': {}, 'text': 'text',
                                         'parameter_content': [{'tag': 'parameterName', 'attributes': {}, 'text': 'feature'},
                                                               {'tag': 'newValue', 'attributes': {}, 'text': 'ECPRI_MSG5_DELAY_MEASUREMENT'},
                                                               {'tag': 'prevValue', 'attributes': {}, 'text': None}]},
                                         {'tag': 'parameter', 'attributes': {}, 'text': 'text',
                                          'parameter_content': [{'tag': 'parameterName', 'attributes': {}, 'text': 'support'},
                                                                {'tag': 'newValue', 'attributes': {}, 'text': 9},
                                                                {'tag': 'prevValue', 'attributes': {}, 'text': None}]}]}
        :type element: dict
        :param searched_content: Dictionary or list of dicts with keys as searched children and values as the grandchild elements to search for. e.g.:
                                 [{"tag": "parameter", "parameter_content": [{"tag": "parameterName", "text": "feature"},
                                                                             {"tag": "newValue", "text": "ECPRI_MSG5_DELAY_MEASUREMENT"}]},
                                  {"tag": "parameter", "parameter_content": [{"tag": "parameterName", "text": "support"},
                                                                             {"tag": "newValue", "text": 9}]}]
        :type searched_content: dict | list[dict]
        :return True if all content is found in the element, False otherwise.
        :rtype: bool
        """
        if not isinstance(searched_content, list):
            searched_content = [searched_content]

        children_with_content = element.get(f'{element["tag"]}_content', [])

        for child in children_with_content:
            for content in searched_content:
                if XmlFile._is_content_present(child, content):
                    searched_content.remove(content)

        return not searched_content

    @staticmethod
    @log_input_and_output
    def _get_all_children_for_element(element):
        """
        Gets list of dicts with tags, attributes and texts of all children of given element.
        :param element: Element object
        :type element: Element
        :return List of dicts with children info for given element, e.g. :
                [{'tag': 'parameterName', 'attributes': {}, 'text': 'Timestamp'},
                 {'tag': 'value', 'attributes': {}, 'text': '2024-05-20T11:30:30-00:00'}]
        :rtype: list of dict
        """
        children_info = []
        for child in element:
            child_info = {'tag': child.tag, 'attributes': child.attrib, 'text': child.text}
            children_info.append(child_info)
        return children_info

    @staticmethod
    def _is_content_present(child_element, search):
        """
        Determines whether the specified search content is present in a child_element.
        :param child_element: The child element from `get_custom_elements_children_and_grandchildren` method, e.g.:
                        {'tag': 'param', 'attributes': {}, 'text': 'text',
                         'param_content': [{'tag': 'parameterName', 'attributes': {}, 'text': 'feature'},
                                           {'tag': 'newValue', 'attributes': {}, 'text': 'ECPRI_MSG5'},
                                           {'tag': 'prevValue', 'attributes': {}, 'text': None}]}
        :type child_element: dict
        :param search: The content to search for in the child element, e.g.:
                       {"tag": "param", 'param_content': [{"tag": "parameterName", "text": "feature"}, {"tag": "newValue", "text": "ECPRI_MSG5"}]}
        :type search: dict
        :return: True if all elements in `searched_content` exist in `child_element`, otherwise False.
        :rtype: bool
        """
        for key, value in search.items():
            if key not in child_element:
                return False

            if isinstance(value, list):
                if not isinstance(child_element[key], list):
                    return False

                if not all(any(XmlFile._is_content_present(e, v) for e in child_element[key]) for v in value):
                    return False

            elif isinstance(value, dict):
                if not isinstance(child_element[key], dict) or not XmlFile._is_content_present(child_element[key], value):
                    return False

            else:
                if str(child_element[key]) != str(value):
                    return False

        return True

    @staticmethod
    @log_input_and_output
    def repair_xml_file(path_to_xml):
        """
        Repairs XML file.
        :param path_to_xml: Absolute path to XML file e.g "/home/ute/Desktop/CRT_Test/TEST/file.xml"
        :type path_to_xml: str
        """
        XmlFile._create_file_copy(path_to_xml)
        XmlFile._add_root_tag_if_not_exists(path_to_xml)
        parser = etree.XMLParser(recover=True)
        tree = etree.parse(path_to_xml, parser)
        with open(path_to_xml, 'wb') as file:
            tree.write(file, pretty_print=True, encoding="utf-8", xml_declaration=False)

    @staticmethod
    def _add_root_tag_if_not_exists(path_to_xml):
        """
        Adds the <root> tag at the beginning of the XML file if it does not exist within the first two lines of the file.
        """
        with open(path_to_xml, 'r+') as file:
            data = file.read()
            if any('<root>' in line for line in data[:2]):
                return
            file.seek(0)
            file.write('<root>' + data)

    @staticmethod
    def _create_file_copy(path_to_xml):
        """
        Creates a copy of the file.
        """
        dir_path = os.path.dirname(path_to_xml)
        os.system(f'cp {path_to_xml} {dir_path}/original_{os.path.basename(path_to_xml)}')
